<?php

declare(strict_types=1);

namespace App\Service;

use App\Entity\PlanningLine;
use App\Entity\PlanningPeriodStatus;

/** What the pipeline needs to run for one line, as observed right now. */
final readonly class LaunchLineReadiness
{
    /** docs/decisions.md D195: the line is (re)generated by this launch — when no blocker applies. */
    public const GENERATE = 'GENERATE';
    /** Its period is validated, published or archived: never regenerated, its current calendar is a commitment. */
    public const KEEP = 'KEEP';
    /** Nothing demanded of it in the period (LineApplicability::NO_DEMAND): left out, untouched, never a blocker. */
    public const EXCLUDE = 'EXCLUDE';

    /**
     * @param array<string, int> $familyUnitCounts REQUIRED DutyUnit count per
     *                                             AllocationFamily name (docs/decisions.md D137)
     *                                             — keyed by the family's own display name,
     *                                             never a hardcoded label; a unit whose pattern
     *                                             carries no family is counted under the empty
     *                                             string key, which the API layer renders as
     *                                             "Sans famille" — counted once per unit, never
     *                                             once per constituent Duty (D136 Scenario F).
     */
    public function __construct(
        public PlanningLine $line,
        public int $memberCount,
        public int $dutyCount,
        public PlanningPeriodStatus $periodStatus,
        public bool $hasActiveRuleSet,
        public array $familyUnitCounts = [],
        /**
         * The line it reinforces, for a conditional line (docs/decisions.md D162/D164): its reinforcements are
         * decided only once that line is assigned, so none is counted in $familyUnitCounts — never a guessed number.
         */
        public ?PlanningLine $demandSourceLine = null,
        /** docs/decisions.md D195: GENERATE, KEEP or EXCLUDE. */
        public string $decision = self::GENERATE,
        /** docs/decisions.md D194/D195: why the line takes part in the period, or not. */
        public ?LineApplicability $applicability = null,
    ) {
    }

    public function isGenerated(): bool
    {
        return self::GENERATE === $this->decision;
    }
}
